(7018528, 1063861, 136989, '<td valign="top">This is a cool shot.  I personally like it better without the reflection but still cool.</td>', 'This is a cool shot.  I personally like it better without the reflection but still cool.', '2013-04-12 02:06:56.000000', NULL, 1),
(7018533, 1063862, 136989, '<td valign="top">This is my hands down favorite in this challenge. (And not just because its purple). The colors are intense and delineated in their shades, there''s a touch of humor and a lot of superior lighting. I love it!!</td>', 'This is my hands down favorite in this challenge. (And not just because its purple). The colors are intense and delineated in their shades, there''s a touch of humor and a lot of superior lighting. I love it!!', '2013-04-12 02:10:15.000000', NULL, 1),
(7018561, 1063862, 86218, '<td valign="top">Really like this but I would have gone for a much tighter crop. well done on the idea</td>', 'Really like this but I would have gone for a much tighter crop. well done on the idea', '2013-04-12 04:25:10.000000', NULL, 1),
(7018564, 1062823, 86218, '<td valign="top">Lovely pastel colours and elegently done. Love this and welcome break from oversaturated entries. 8</td>', 'Lovely pastel colours and elegently done. Love this and welcome break from oversaturated entries. 8', '2013-04-12 04:29:10.000000', NULL, 1),
