(7019523, 1063929, 54446, '<td valign="top">Elegant curved glass with a good choice of bg subject to view.  Good refraction.</td>', 'Elegant curved glass with a good choice of bg subject to view.  Good refraction.', '2013-04-13 13:54:36.000000', NULL, 1),
(7019524, 1063919, 54446, '<td valign="top">Refraction and reflection.  Very sharp where it counts.  I like the blurred bg.  The inclusion of the gray sky throughout the image, but especially on the mirror, makes the image a bit harsh to view.  I like the natural look and the gray, nondescript sky is a problem for all landscape photographers.</td>', 'Refraction and reflection.  Very sharp where it counts.  I like the blurred bg.  The inclusion of the gray sky throughout the image, but especially on the mirror, makes the image a bit harsh to view.  I like the natural look and the gray, nondescript sky is a problem for all landscape photographers.', '2013-04-13 13:58:11.000000', NULL, 1),
(7019525, 1063862, 54446, '<td valign="top">Good choice of image to refract.  Not sure I like the spilled water.</td>', 'Good choice of image to refract.  Not sure I like the spilled water.', '2013-04-13 13:59:30.000000', NULL, 1),
(7019526, 1062823, 54446, '<td valign="top">Visually... this is a very attractive image.  Work of art, it is!  Great asymmetrical composition.  Probably the best set up shot in the challenge.  This should be a ribbon contender.  10</td>', 'Visually... this is a very attractive image.  Work of art, it is!  Great asymmetrical composition.  Probably the best set up shot in the challenge.  This should be a ribbon contender.  10', '2013-04-13 14:00:57.000000', NULL, 1),
