(7019529, 1063906, 54446, '<td valign="top">Very attractive beer mug.  This one made me laugh.   Excellent composition.</td>', 'Very attractive beer mug.  This one made me laugh.   Excellent composition.', '2013-04-13 14:05:18.000000', NULL, 1),
(7019530, 1063996, 54446, '<td valign="top">Unique combo.  Good refraction.</td>', 'Unique combo.  Good refraction.', '2013-04-13 14:05:58.000000', NULL, 1),
