(7019595, 1063986, 26318, '<td valign="top">Love it..</td>', 'Love it..', '2013-04-13 15:30:07.000000', NULL, 1),
(7019597, 1063815, 54446, '<td valign="top">The subject poster appears to be sharp.  It''s a bit tiny.  But, I get the idea.</td>', 'The subject poster appears to be sharp.  It''s a bit tiny.  But, I get the idea.', '2013-04-13 15:32:24.000000', NULL, 1),
(7019602, 1063849, 54446, '<td valign="top">At the corner of the fish bowl.  This is one of the more creative and unique images in the challenge.   For some reason, the special nature of this photo transcends any technical weakness.  Not sure about the black bg, but I like it anyway.  9</td>', 'At the corner of the fish bowl.  This is one of the more creative and unique images in the challenge.   For some reason, the special nature of this photo transcends any technical weakness.  Not sure about the black bg, but I like it anyway.  9', '2013-04-13 15:36:03.000000', NULL, 1),
(7019604, 1063770, 54446, '<td valign="top">Refraction visible in the rain drops.</td>', 'Refraction visible in the rain drops.', '2013-04-13 15:37:36.000000', NULL, 1),
(7019605, 1062688, 54446, '<td valign="top">Abstract and unusual.  Certainly refraction apparent.  But, those white areas are odd as can be.</td>', 'Abstract and unusual.  Certainly refraction apparent.  But, those white areas are odd as can be.', '2013-04-13 15:38:40.000000', NULL, 1),
(7019606, 1063842, 54446, '<td valign="top">Artistic refraction.</td>', 'Artistic refraction.', '2013-04-13 15:39:17.000000', NULL, 1),
(7019607, 1062794, 54446, '<td valign="top">Humorous.  Refraction apparent, in spite of yourself.  Good job!</td>', 'Humorous.  Refraction apparent, in spite of yourself.  Good job!', '2013-04-13 15:41:00.000000', NULL, 1),
(7019621, 1063735, 54446, '<td valign="top">I''m certain you are showing refraction.  And, the glass is precisely sharp and in focus.  It would be more attractive to me if some of the refracted image showed some sharp lines and shapes.  I like the subject and the title.</td>', 'I''m certain you are showing refraction.  And, the glass is precisely sharp and in focus.  It would be more attractive to me if some of the refracted image showed some sharp lines and shapes.  I like the subject and the title.', '2013-04-13 15:50:40.000000', NULL, 1),
(7019623, 1063868, 54446, '<td valign="top">Love those bubbles and the amazing magnification.  Thanks for getting everything in focus.  I really like this and am giving it my highest score.  10</td>', 'Love those bubbles and the amazing magnification.  Thanks for getting everything in focus.  I really like this and am giving it my highest score.  10', '2013-04-13 15:51:59.000000', NULL, 1),
(7019634, 1063965, 54446, '<td valign="top">Radiating rainbows.  Some of the whites are blown out, but overall the refracted light is obvious.</td>', 'Radiating rainbows.  Some of the whites are blown out, but overall the refracted light is obvious.', '2013-04-13 16:18:58.000000', NULL, 1),
(7019643, 1063920, 54446, '<td valign="top">I do see some refracted light.  This is subtle, like the red in the center right.</td>', 'I do see some refracted light.  This is subtle, like the red in the center right.', '2013-04-13 16:30:54.000000', NULL, 1),
(7019644, 1063861, 54446, '<td valign="top">Must be southern hemisphere to see autumn colors.   Good sharpness and clarity to the glass and refracted image.</td>', 'Must be southern hemisphere to see autumn colors.   Good sharpness and clarity to the glass and refracted image.', '2013-04-13 16:33:29.000000', NULL, 1),
(7019645, 1064017, 54446, '<td valign="top">Very cool.  Abstract for sure.  Great colors.</td>', 'Very cool.  Abstract for sure.  Great colors.', '2013-04-13 16:34:23.000000', NULL, 1),
(7019647, 1063900, 54446, '<td valign="top">The colors are subdued.  Maybe the yellow is drab.  Okay refraction.  I''d like to see some increased focus and sharpness.</td>', 'The colors are subdued.  Maybe the yellow is drab.  Okay refraction.  I''d like to see some increased focus and sharpness.', '2013-04-13 16:36:28.000000', NULL, 1),
