(7022248, 1063851, 100831, '<td valign="top">pretty colors and bokeh.. maybe this is more about reflection than refraction but who cares? 7 - I love the way you caught the light.</td>', 'pretty colors and bokeh.. maybe this is more about reflection than refraction but who cares? 7 - I love the way you caught the light.', '2013-04-17 13:46:55.000000', NULL, 1),
(7022353, 1063646, 38921, '<td valign="top">I really like this shows refraction and reflection. I actually attempted a similar shot for this challenge and I was unable to get the laser to show up in the air.  Hopefully you''ll share your secret when voting is over.</td>', 'I really like this shows refraction and reflection. I actually attempted a similar shot for this challenge and I was unable to get the laser to show up in the air.  Hopefully you''ll share your secret when voting is over.', '2013-04-17 16:18:09.000000', NULL, 1),
(7022391, 1063675, 20799, '<td valign="top">Love those dots. Not an unusual sight but very well executed.</td>', 'Love those dots. Not an unusual sight but very well executed.', '2013-04-17 18:54:27.000000', NULL, 1),
(7022407, 1063646, 20799, '<td valign="top">I almost entered something similar, although not nearly as good. Good control of the bright light.</td>', 'I almost entered something similar, although not nearly as good. Good control of the bright light.', '2013-04-17 19:09:01.000000', NULL, 1),
(7022429, 1063924, 38921, '<td valign="top">I''m not sure this is refraction however I am giving you the benefit of the doubt that it is not a reflection. <br/> <br/>I love this and it plays well in black and white, one of my two 10''s for this challenge.</td>', 'I''m not sure this is refraction however I am giving you the benefit of the doubt that it is not a reflection.  I love this and it plays well in black and white, one of my two 10''s for this challenge.', '2013-04-17 19:22:40.000000', NULL, 1),
(7022430, 1062889, 38921, '<td valign="top">Beautiful light here, one of my two 10''s for the challenge.</td>', 'Beautiful light here, one of my two 10''s for the challenge.', '2013-04-17 19:23:32.000000', NULL, 1),
(7022435, 1063464, 38921, '<td valign="top">I like the colors and the layout of the background here, 6.<br/> <br/>This could have easily scored a point or two higher for me if all of the drops where tack sharp. The top right looks good and it gets softer as you move left and down. This is likely due to the camera sensor not being perfectly parallel to glass the drops are on.</td>', 'I like the colors and the layout of the background here, 6. This could have easily scored a point or two higher for me if all of the drops where tack sharp. The top right looks good and it gets softer as you move left and down. This is likely due to the camera sensor not being perfectly parallel to glass the drops are on.', '2013-04-17 19:30:37.000000', NULL, 1),
(7022441, 1064019, 38921, '<td valign="top">Very cool and thanks for teaching me a new word.</td>', 'Very cool and thanks for teaching me a new word.', '2013-04-17 19:32:57.000000', NULL, 1),
(7022452, 1063911, 159525, '<td valign="top">Beautiful choice of colors!  They are very complimentary.</td>', 'Beautiful choice of colors!  They are very complimentary.', '2013-04-17 19:40:45.000000', NULL, 1),
(7022470, 1063900, 97225, '<td valign="top">Well caught. They really look like they are in there.</td>', 'Well caught. They really look like they are in there.', '2013-04-17 20:19:12.000000', NULL, 1),
(7022475, 1063979, 97225, '<td valign="top">I love the different forms the refractions take within the different forms of the swizzle sticks. The range of wild colours really define those forms.</td>', 'I love the different forms the refractions take within the different forms of the swizzle sticks. The range of wild colours really define those forms.', '2013-04-17 20:26:34.000000', NULL, 1),
(7022476, 1063684, 97225, '<td valign="top">Gorgeous refraction and beautiful bright colour.</td>', 'Gorgeous refraction and beautiful bright colour.', '2013-04-17 20:27:11.000000', NULL, 1);
